from build import save
rows=[
(181,['天狂胜弩手后被16药魔药术暴击秒，转由夜落出场，喝23种含彩药、近宗师尚差2熟练，成本过万、属性约敌1.5倍。'],['药师专业等级与储备成擂台主要变量。'],[],7324,7377),
(182,['夜落赢魔药后主办以强敌耗光五份最强药，第九胜后第十被未成年皇冠狮鹫骑士杀，仍尽力展其攻击供队友看。萧翎以毁术身份登台、全智五传说法伤2600，仅用少量技能胜德鲁伊。'],['前队员耗药与败局构成主角情报积累。'],[],7381,7415),
(183,['萧翎逐步露痛术与恶魔技能，抗拒破冰环、恐惧击败冰雷，炎魔逼走位再恐惧胜魔药；九胜仍藏机械。'],['主办从确定双职改为怀疑三职，信息预算逐层消耗。'],[],7419,7477),
(184,['末敌风骑报姓名；萧翎有阿卡德祝福和夜落7000防药。顶狮鹫俯冲受电芒重伤，恐惧后首次公开石像鬼冰环，四职曝光。'],['隐藏能力全部出场；成功依赖团队支持状态。'],[],7483,7516),
(185,['石像鬼贴身肉搏令长枪失用，风骑冒死俯冲被冰环卡在20码惯性致坠亡。钱通认输发百万、三传说及史诗魔力源泉，公开属性促销减费；源泉20%魔量、5%回复、六小时回满，牧师无效，非唯一。'],['十胜达成，主办将损失转为宣传并披露奖励。'],[],7520,7563),
(186,['主角领奖先不绑定源泉，团员同意输出最大者留用才绑定至约3600魔。天狂启动湛蓝翡翠宝石收购；会钱通得两传说换以后不打擂，未明确接受每场十万协助义务。钱通转狂龙千万收附属团邀请。'],['共同贡献经分配再个人绑定；敌对生意转成互不为难。'],['狂龙邀请如何拒？'],7567,7613),
(187,['天狂以龙之焰客卿不得入别会婉拒，退出原会实际为客卿妥协。牧琳私房钱购机械体悟技能赠主角，团队采购一湛蓝。天狂解释属性适配优先稀有级，狂龙估两亿是他的估值。'],['旧公会束缚转为抗吞并屏障；人物关系以付费行动表达。'],['客卿屏障是否长期有效？'],7617,7648),
(188,['讨论最高难任务与前线追差距，天狂暂以43–45适合未立即出征。无炎领三拨轮休、练级、PK，三天剔1新冰法，训练技术普涨。提及397另两名幸存女性也入游戏但无炎不知处。'],['从高手集合转可训练组织；前线尚为筹议。'],['两女性机师是谁在哪？'],7652,7685),
(189,['三天萧39团34，整十五天萧46榜376、团41；狂龙51。烈焰套镶嵌附魔雷冰采购，众表决前线，待晶碎齐。发现奥托姆博古堡，卧室完好、走廊火烧；罗格眼无怪，推火山口找领主。'],['闭关成长兑现；前线获得团队决策。'],['卧室为何独完好？'],7689,7723),
(190,['萧、牧琳、乱影三人侦火山，用罗格眼越怪群发现40强化火焰领主及宝箱。乱影引怪、牧琳凭盗神钥开锁、萧准备接应并给逃生药。'],['领主位置确认但任务尚未接；寻宝进入执行。'],[],7727,7769),
(191,['傀儡分引余怪，萧控群救牧琳，三人脱身得稀有五阶完美火晶+10%火伤，暂无配套装备。回城见霍尔卡德，父奥托姆博守卧室三日救幼子后灼亡，解释遗址。'],['宝箱已取；古堡异常回收为父爱行动。'],['复仇之旅有何代价？'],7773,7821),
(192,['听父事触主角父亲记忆，接任务。霍尔要求与领主单挑不得插手。先清两头领，团双盾人墙压住一只，33远程无视仇恨全输2分21杀；罗格眼绕发现门槛降难由NPC分担另一只。'],['高法系团队方案首次充分验证；进入领主洞穴。'],[],7825,7864),
(193,['夜落3000回复半成品供NPC，称高回魔也半成品无法量产未宗师。霍尔单挑显恶魔气，透露卖信仰给炎使得魔炎咒，诅咒杀火焰领主莫里多纳。愿回故乡受审，众不杀他，收三传承装，铠字劝子表达父爱。'],['领主击杀与装备交付完成；霍尔回审仅意愿/去向，未显示审判结果。'],['战神之殿如何审霍尔？'],7868,7909),
]
d={
'worldbuilding':[['魔药术自用高阶药依个体体质配套、顺序不可乱；强度受有限储备与原料供给限制。','fact',[181,7336,7377],[182,7383,7388]],['魔力源泉非唯一365枚，在包生效但牧师无效，主动回满冷却六小时，不能等同普遍无限蓝。','fact',[185,7556,7563]],['机械意识也可转新宝石；采购湛蓝每颗万、翡翠八千共九万且市场稀缺，尚在囤货。','fact',[186,7589,7593]],['双盾人墙下无视仇恨输出以坦技、牧反应及全队应急能力为前提，不是仇恨规则消失。','fact',[192,7850,7853]]],
'characters':[['萧翎领奖暂拒绑定、向团交付后才留用，把共同成就与个人成长的归属冲突显式化解。','fact',[186,7569,7587]],['天狂将公会客卿限制化为第三方屏障，兼以资源循环保留团自主权。','fact',[187,7618,7628],[186,7587,7593]],['霍尔卡德的荣耀承诺与卖信仰复仇并存，父子身份使玩家对他采用宽容判断，未直接等于神赦。','fact',[192,7833,7836],[193,7899,7909]]],
'plot':[['风骑最大优势俯冲动量在冰环定点释放时变成摔死原因，既有体型、武器与冷却规则重新组合获胜。','inference',[184,7492,7508],[185,7524,7539]],['古堡卧室无烧迹先立异常，回叙父亲三日守门解释空间分布，复仇动机又带出售魂代价。','inference',[189,7714,7719],[191,7820,7821],[193,7893,7905]],['擂台胜利后接社会关系后果：钱通商业和解、狂龙收购、借客卿拒绝，避免领奖即清零。','inference',[185,7541,7550],[186,7599,7613],[187,7618,7628]]],
'style':[['公众震惊随着双系、三系、四系逐层重复，数值与围观视角共同放大爽点；重复过密会钝化。','inference',[183,7431,7459],[184,7508,7516]],['父子段从提问式故乡对话转回护门行动，再以铠甲一句铭文作情感落点，优于只写父爱抽象评价。','inference',[191,7808,7821],[193,7907,7909]]],
'narrative':[['天狂对狂龙装备两亿的估计明确是角色估值，不能提升为已审计资产事实。','fact',[187,7645,7648]],['193先以外人感到恶魔气形成疑问，再让霍尔坦承卖信仰揭答案；主角宽容不抹去其自认罪责与审判意愿。','fact',[193,7893,7905]],['189主角担心冲榜触发军备竞争是风险预测，当前只实际到46，并未已超狂龙。','fact',[189,7695,7699]]],
'dialogue':[['钱通把损失包装成庆祝与降价活动，对外宣传、对内两装换止擂，两个场合各有利益目标。','inference',[185,7541,7550],[186,7599,7609]],['父与子的连问连答让故乡地图承载童年亲密，之后父亲临终希望与儿子自责形成情感落差。','inference',[191,7808,7821]],['“你是父亲的孩子”回应把霍尔自称恶魔信徒的单一道德标签转回具体关系，是人物判断而非系统洗罪。','inference',[193,7901,7905]]],
'pacing':[['夜落九胜压缩为药耗清单，狮鹫终局展开；主角逐职业解锁后最终用傀儡，信息保留控制竞技长度。','inference',[182,7383,7407],[183,7423,7477]],['十五日训练以三阶段刷怪与等级装备变化概括，随后完整展开遗址侦察、分工开箱和复仇，把重复劳动与新决策区分篇幅。','inference',[189,7692,7705],[190,7729,7769],[191,7773,7796]]],
'themes':[['胜利属于共同情报、药剂、祝福及最终执行，文本主动交代支持条件，避免单人胜利遮蔽团队。','fact',[184,7490,7491],[185,7540,7540],[186,7572,7587]],['稀有标签不必然胜于功能适配，机械身弱与傀儡强的极端成长提醒多职有互补也有投资焦点。','fact',[187,7639,7646]],['父爱与复仇信仰冲突给原“神决定善恶”框架增加人际宽容；是否获神赦仍未出现。','inference',[193,7899,7909]]],
'continuity':[['机械体悟在同章稍后称傀儡体悟，记录异名不另建技能。','fact',[187,7639,7642]],['火焰领主任务从发现奖励到找到位置到系统接收再杀与交装，四状态明确不同。','fact',[175,7078,7080],[190,7738,7741],[192,7828,7831],[193,7902,7906]],['夜落距宗师2熟练未完成；高回复药半成品、回魔半成品不量产，不能提前宣称宗师或高药量产。','fact',[181,7372,7376],[193,7872,7876]],['此前拆毁意识限制经174换身、186明确可转宝石，后半核对应按后明确规则但保留前文差异。','fact',[44,1685,1688],[174,7031,7032],[186,7589,7590]]],
}
c=[dict(key='xiao-ling',name='萧翎',aliases=[],summary='完成转职后随团闭关，46级榜376；擂台十胜全四职公开，绑定魔力源泉约3600魔，曜银双技石像鬼、200%速马。',goals=['以团队积累支持长线第一','先随团去埃拉西亚前线'],changes=['主动不急冲榜以免根基不足','个人奖励经团确认','面对恶魔信徒霍尔选择理解'],relationships=['牧琳以私房钱技能支持，亲密已推进','与天狂双核心分工','无炎步法学九成是叙述称'],knowledge=['完成侦察协助火领主，知道霍尔背信来源'],source_anomalies=['擂台气爆解释精神而前全智路径，保留原说不重算','团队同时称21新成员剔1，48人数与此前27+21一致终47未再明确报数'],evidence=[[182,7407,7415],[186,7572,7586],[187,7633,7642],[189,7695,7703],[193,7899,7906]]),dict(key='tian-kuang',name='天狂',aliases=[],summary='团长、双系牧师；龙之焰客卿不得入别会而行动自由。组织收购分配、训练、表决去前线。',goals=['建一流团队保持自主','通过前线追装备差距'],changes=['借客卿拒千万收购','反复展示共享资源原则','确定表决后前线计划'],relationships=['钱通互不再擂协议','无炎负责全团训练','林菲采购管理'],knowledge=['狂龙装备两亿仅估计'],source_anomalies=[],evidence=[[186,7580,7609],[187,7620,7628],[188,7668,7677],[189,7700,7703]]),dict(key='holkad',name='霍尔卡德',aliases=[],summary='奥托姆博之子、老年野蛮狂战，五十年前被父舍命守卧室；卖信仰给炎之使魔得咒，亲杀莫里多纳，交传承装后离去。',goals=['以领主心祭父','回埃弗蒙战神殿受审'],changes=['慈厚讲父到战中黑气','复仇完成并承认欺骗'],relationships=['奥托姆博儿子、雷蒙卡德孙','向牧野等托付三件装备'],knowledge=['父曾刺心未杀领主，故寻特殊咒'],source_anomalies=[],evidence=[[191,7807,7821],[192,7833,7836],[193,7881,7909]]),dict(key='qian-tong',name='钱通',aliases=['PK场负责人'],summary='主办擂台、售录像情报，履行奖励并把败绩转宣传；两装换天狂团不再挑战，代狂龙邀约。',goals=['保持生意','保护高端装备资产'],changes=['不了解新团至全力探底再寻和解'],relationships=['对接各大公会与狂龙','风骑为其压阵骑士'],knowledge=['有两史诗选留冰雷袍，另发源泉'],source_anomalies=[],evidence=[[185,7541,7563],[186,7599,7613]])]
s=[dict(key='l-scene-griffin-inertia',title='把极速优势变为刹不住的弱点',summary='傀儡贴身攀附，等俯冲近地20码冰环锁死使风骑坠亡。',goal='赢终局而保持自身存活',obstacle='敌占70码空域、俯冲高伤与解恐惧技',choice='承首轮取贴身机会，以近战傀儡纠缠，等冷却和不可刹距离',consequence='敌自摔败，团队得十胜奖励',state_change='机械最后底牌曝光换明确胜果',why_it_works='控制不是简单扣血而改变运动条件，早前速度和长枪优势都成弱点。',applicability='强敌能力具有物理限制且主角可控制时机',failure_mode='没有铺垫惯性、制动和技能冷却，就成临时规则杀。',evidence=[[184,7492,7508],[185,7523,7540]]),dict(key='l-scene-shared-prize',title='先交共有权再绑定个人奖励',summary='源泉先不绑定，庆功时全交团，再经适配讨论留主角。',goal='让稀有个人装备服务共同发展',obstacle='最终执行者和前序贡献者权益不同',choice='主动开放分配而由众人按输出确认',consequence='主角魔量提升同时团队认同加强',state_change='装备爽点兼作组织信任证据',why_it_works='暂缓不可逆绑定使公平有实际行为，而非事后口号。',applicability='团队共同攻克而奖励只有一份',failure_mode='永远自动给主角、队友无自身需求则礼让空洞。',evidence=[[186,7569,7587]]),dict(key='l-scene-father-room',title='完整卧室背后的三日守门',summary='废堡唯一完好卧室由父亲死守解释，儿子用背信代价复仇。',goal='霍尔亲自祭父，玩家完成协助',obstacle='父杀不死的领主与背信后果',choice='儿子卖信仰取咒，团队尊其不干预并接受其身份坦白',consequence='领主死、三装交付、霍尔拟回受审',state_change='寻宝协助线转为具体父子伦理，未给审判终果',why_it_works='空间证据先让读者疑问，回叙行动证明父爱；装备铭文把情感带出任务现场。',applicability='遗址、遗物与关系史相互解释的短篇支线',failure_mode='靠大段告白替代可见行为，或以亲情取消一切行为后果。',evidence=[[189,7714,7719],[191,7820,7821],[192,7833,7836],[193,7893,7909]])]
